#include "../../../../rgb-openrgb-2026-11-05/effects-source/OpenRGB/qt/hsv.h"
#include "../../../../rgb-openrgb-2026-11-05/effects-source/Dependencies/SimplexNoise/src/SimplexNoise.h"
#include <fstream>
int main(){std::ifstream in("gradient-fixtures.bin",std::ios::binary);in.seekg(600);unsigned char lut[300];in.read((char*)lut,300);std::ofstream out("noise-fixtures.bin",std::ios::binary);SimplexNoise noise(.12f,3.9f,.75f,.5f);for(int choice=0;choice<3;choice++)for(int motion=0;motion<4;motion++){double progress=0;for(int frame=0;frame<200;frame++){float xs=0,ys=0;switch(motion){case 0:ys=7*progress;break;case 1:ys=7*-progress;break;case 2:xs=7*progress;break;case 3:xs=7*-progress;break;}for(unsigned int y=0;y<4;y++)for(unsigned int x=0;x<8;x++){float value=noise.fractal(2,x+xs,y+ys,progress);float frac=(1+value)*.5;unsigned int c;if(choice<2){hsv_t h;h.hue=choice==0?360*frac:360-360*frac;h.saturation=255;h.value=255;c=hsv2rgb(&h);}else{int cx=(1-frac)*100;if(cx<0||cx>=100)return 2;c=lut[cx*3]|(lut[cx*3+1]<<8)|(lut[cx*3+2]<<16);}out.write((char*)&c,4);}progress+=.1*(float)40/(float)48;}}return out.good()?0:1;}
